<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Process Return / Exchange</title><style>body{font:15px Arial;background:#f4f6fa;color:#172b43}.wrap{max-width:1050px;margin:30px auto}.card{background:#fff;padding:22px;border-radius:12px;margin:15px 0}input,select{padding:10px;border:1px solid #ccd5df;border-radius:6px;margin:4px;max-width:100%}button,a{background:#173d65;color:#fff;padding:10px 14px;border:0;border-radius:7px;text-decoration:none;cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #eee}.line{display:flex;gap:8px;flex-wrap:wrap}</style></head><body><main class="wrap"><h1>Return / Exchange</h1><p><a href="{{ route('sales.index') }}">Back to Sales</a></p><div class="card"><h2>Original Receipt: {{ $sale->receipt_number }}</h2><p>Branch: {{ $sale->branch->name }} · Date: {{ $sale->sold_at->format('d M Y H:i') }} · Original Total: PKR {{ number_format($sale->total_amount,2) }}</p><table><tr><th>Return?</th><th>Item</th><th>Sold Qty</th><th>Return Qty</th><th>Original Unit Price</th></tr>@foreach($sale->items as $i)<tr><td><input type="checkbox" class="return-check" onchange="toggleReturn({{ $loop->index }})"></td><td>{{ $i->product_name }} / {{ $i->sku }} / {{ $i->size }} / {{ $i->color }}</td><td>{{ $i->quantity }}</td><td><input disabled class="return-qty" id="qty{{ $loop->index }}" type="number" min="1" max="{{ $i->quantity }}" value="1" style="width:75px"></td><td>{{ number_format($i->unit_price,2) }}</td></tr>@endforeach</table></div><form method="POST" action="{{ route('returns.store',$sale) }}" onsubmit="return prepareReturn()">@csrf<div id="returnHidden"></div><div class="card"><label>Action</label><select name="return_type" id="returnType" onchange="toggleExchange()"><option value="refund">Refund</option><option value="exchange">Exchange</option></select><label>Reason</label><input name="reason" required style="width:70%" placeholder="Reason for return / exchange"><label>Refund Method</label><select name="refund_method"><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option><option value="mobile_wallet">Mobile wallet</option><option value="other">Other</option></select></div><div class="card" id="exchangeBox" style="display:none"><h2>Replacement Items</h2><div id="replacementRows"><div class="line"><select class="replacement-field" name="replacement_items[0][product_variant_id]" disabled><option value="">Choose replacement shoe / SKU</option>@foreach($variants as $v)<option value="{{ $v->id }}">{{ $v->product->name }} — {{ $v->size }}/{{ $v->color }} ({{ $v->sku }}) — PKR {{ number_format($v->selling_price,2) }}</option>@endforeach</select><input class="replacement-field" type="number" name="replacement_items[0][quantity]" min="1" value="1" disabled style="width:90px"></div></div><button type="button" onclick="addReplacement()">+ Add replacement item</button><p>Returned items are added back to stock. Replacement items are deducted from stock. Any exchange balance must be paid before completion.</p><label>Payment Method for Additional Amount</label><select name="payment_method"><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option><option value="mobile_wallet">Mobile wallet</option><option value="other">Other</option></select><label>Amount Paid</label><input type="number" min="0" step=".01" name="amount_paid" value="0"></div><button>Complete Return / Exchange</button></form></main><script>
function toggleReturn(i){const on=document.querySelectorAll('.return-check')[i].checked;document.getElementById('qty'+i).disabled=!on}
function toggleExchange(){const on=document.getElementById('returnType').value==='exchange';document.getElementById('exchangeBox').style.display=on?'block':'none';document.querySelectorAll('.replacement-field').forEach(x=>x.disabled=!on)}
let replacementIndex=1;function addReplacement(){const c=document.querySelector('#replacementRows .line').cloneNode(true);c.querySelectorAll('select,input').forEach(e=>{e.name=e.name.replace(/replacement_items\[0\]/,'replacement_items['+replacementIndex+']');if(e.tagName==='SELECT')e.selectedIndex=0;else e.value='1'});document.getElementById('replacementRows').appendChild(c);replacementIndex++}
const saleItemIds = @json($sale->items->pluck('id')->values());
function prepareReturn(){const hidden=document.getElementById('returnHidden');hidden.innerHTML='';let count=0;document.querySelectorAll('.return-check').forEach((cb,i)=>{if(cb.checked){const qty=document.getElementById('qty'+i);const row=document.createElement('div');row.innerHTML='<input type="hidden" name="items['+count+'][sale_item_id]" value="'+saleItemIds[i]+'"><input type="hidden" name="items['+count+'][quantity]" value="'+qty.value+'">';hidden.appendChild(row);count++}});if(!count){alert('Select at least one original item to return.');return false}if(document.getElementById('returnType').value==='exchange'&&!document.querySelector('#replacementRows select').value){alert('Select replacement items.');return false}return true}
</script></body></html>